"use client";

import { useInView } from "motion/react";
import { useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import type { Status } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { ChevronRightIcon } from "../parts/icons";
import { RollingText } from "../parts/rolling-text";
import { objectivePercent, type Objective, QUARTERS } from "./goal-tracker/data";
import { ObjectiveRow } from "./goal-tracker/objective-row";
import { ChevronLeftIcon } from "./shared/icons";

const overall = (objectives: Objective[]) =>
  objectives.length === 0 ? 0 : objectives.reduce((total, objective) => total + objectivePercent(objective), 0) / objectives.length;

/**
 * A team's goals for a quarter. Step between last quarter's final scores, this
 * quarter and next quarter's plan. Open an objective to see its key results,
 * then check in on one: the key result's bar moves first and the objective's
 * bar follows.
 */
export function GoalTracker({ className }: { className?: string }) {
  const [quarters, setQuarters] = useState(QUARTERS);
  const [quarterIndex, setQuarterIndex] = useState(1);
  const [openId, setOpenId] = useState<string | null>("q4-b");
  const [checkingIn, setCheckingIn] = useState<string | null>(null);
  const [saved, setSaved] = useState("");
  const frameRef = useRef<HTMLDivElement>(null);
  const shown = useInView(frameRef, { once: true, amount: 0.3 });
  const titleId = useId();

  const quarter = quarters[quarterIndex]!;
  const editable = quarter.state === "current";
  const percent = overall(quarter.objectives);

  const stepQuarter = (step: number) => {
    setQuarterIndex((index) => Math.max(0, Math.min(quarters.length - 1, index + step)));
    setOpenId(null);
    setCheckingIn(null);
  };

  const save = (resultId: string, next: { current: number; confidence: Status; note: string }) => {
    setQuarters((current) =>
      current.map((item) => ({
        ...item,
        objectives: item.objectives.map((objective) => ({
          ...objective,
          results: objective.results.map((result) =>
            result.id === resultId ? { ...result, current: next.current, confidence: next.confidence } : result,
          ),
        })),
      })),
    );
    setCheckingIn(null);
    setSaved(next.note ? "Check-in saved with your note." : "Check-in saved.");
  };

  const firstOpenResult = () => {
    const objective = quarter.objectives.find((item) => item.id === openId) ?? quarter.objectives[0];
    const result = objective?.results[0];
    if (!objective || !result) return;
    setOpenId(objective.id);
    setCheckingIn(result.id);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-2xl", className)}>
      <div ref={frameRef}>
        <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="flex items-baseline gap-2 text-base font-semibold">
              Clinic growth goals
              <RollingText text={`${Math.round(shown ? percent : 0)}%`} className="text-sm font-medium text-muted-foreground" />
            </h2>
            <p className="text-sm text-muted-foreground">{quarter.when}</p>
          </div>
          <div className="flex items-center gap-1" role="group" aria-label="Quarter">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => stepQuarter(-1)}
              disabled={quarterIndex === 0}
              aria-label="Previous quarter"
            >
              <ChevronLeftIcon />
            </Button>
            <span className="min-w-20 text-center text-sm font-medium tabular-nums" aria-live="polite">
              {quarter.label}
            </span>
            <Button
              variant="ghost"
              size="icon"
              onClick={() => stepQuarter(1)}
              disabled={quarterIndex === quarters.length - 1}
              aria-label="Next quarter"
            >
              <ChevronRightIcon />
            </Button>
          </div>
        </header>

        {quarter.state !== "current" ? (
          <p className="border-b border-border px-5 py-2 text-xs text-muted-foreground">
            {quarter.state === "closed" ? "Final scores. This quarter is closed." : "Draft goals. Check-ins open on Jan 4."}
          </p>
        ) : null}

        <ul aria-label={`Objectives for ${quarter.label}`}>
          {quarter.objectives.map((objective) => (
            <ObjectiveRow
              key={objective.id}
              objective={objective}
              open={openId === objective.id}
              onToggle={() => {
                setOpenId(openId === objective.id ? null : objective.id);
                setCheckingIn(null);
              }}
              checkingIn={checkingIn}
              onCheckIn={setCheckingIn}
              onSave={save}
              editable={editable}
              shown={shown}
            />
          ))}
        </ul>

        <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-3">
          <p className="text-xs text-muted-foreground" role="status">
            {saved || (editable ? "Next check-in Monday, Nov 16" : `${quarter.objectives.length} objectives`)}
          </p>
          {editable ? (
            <Button size="sm" onClick={firstOpenResult}>
              Check in
            </Button>
          ) : null}
        </footer>
      </div>
    </BlockFrame>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

