import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import type { Status } from "../../lib/status";

/** One measurable result under an objective. Progress is `current` from `start` toward `target`. */
export interface KeyResult {
  id: string;
  title: string;
  start: number;
  current: number;
  target: number;
  /** Written after the figure, such as "%" or " clinics". */
  unit: string;
  confidence: Status;
}

/** One objective, owned by one person, with its key results. */
export interface Objective {
  id: string;
  title: string;
  owner: string;
  results: KeyResult[];
}

/** One quarter of goals. A closed quarter shows final scores and takes no check-ins. */
export interface Quarter {
  id: string;
  label: string;
  /** The line under the title, such as "Week 7 of 13". */
  when: string;
  state: "closed" | "current" | "planning";
  objectives: Objective[];
}

/** How far a key result has moved from its start toward its target, from 0 to 100. */
export function resultPercent(result: KeyResult) {
  const span = result.target - result.start;
  if (span === 0) return 100;
  return Math.max(0, Math.min(100, ((result.current - result.start) / span) * 100));
}

/** An objective's progress: the mean of its key results. */
export function objectivePercent(objective: Objective) {
  if (objective.results.length === 0) return 0;
  return objective.results.reduce((total, result) => total + resultPercent(result), 0) / objective.results.length;
}

/** The weakest confidence among an objective's key results, so a risk is never hidden by an average. */
export function objectiveConfidence(objective: Objective): Status {
  const states = objective.results.map((result) => result.confidence);
  if (states.includes("bad")) return "bad";
  if (states.includes("watch")) return "watch";
  return "good";
}

