"use client";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Content as Disclosed, Root as Disclosure, Trigger as DisclosureTrigger } from "@radix-ui/react-collapsible";

import type { Status } from "../../lib/status";
import { ChevronRightIcon } from "../../parts/icons";
import { RollingText } from "../../parts/rolling-text";
import { PersonAvatar } from "../shared/avatar";
import { person } from "../shared/people";
import { ProgressBar } from "../shared/progress-bar";
import { CheckInForm } from "./check-in-form";
import { ConfidencePill } from "./confidence-pill";
import { type Objective, objectiveConfidence, objectivePercent, resultPercent } from "./data";

/** Props for one objective with its key results. */
export interface ObjectiveRowProps {
  objective: Objective;
  open: boolean;
  onToggle: () => void;
  /** The key result whose check-in form is open, if any. */
  checkingIn: string | null;
  onCheckIn: (resultId: string | null) => void;
  onSave: (resultId: string, next: { current: number; confidence: Status; note: string }) => void;
  /** False for a closed quarter: it shows final scores only. */
  editable: boolean;
  /** False until the card scrolls into view, so the bars fill in front of the reader. */
  shown: boolean;
}

const BAR_FILL = { good: "bg-chart-2", watch: "bg-chart-4", bad: "bg-chart-5" } satisfies Record<Status, string>;
const formatValue = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });

/**
 * One objective: a disclosure that opens it, its owner, its confidence and a bar.
 * Open, it lists the key results, each with a check-in. The objective's bar
 * moves a moment after a key result's bar, so the cause reads first.
 */
export function ObjectiveRow({ objective, open, onToggle, checkingIn, onCheckIn, onSave, editable, shown }: ObjectiveRowProps) {
  const owner = person(objective.owner);
  const percent = objectivePercent(objective);
  const confidence = objectiveConfidence(objective);

  return (
    <Disclosure asChild open={open} onOpenChange={onToggle}>
      <li className="border-b border-border last:border-b-0">
        <h3>
          <DisclosureTrigger className="group relative isolate flex w-full cursor-pointer flex-col gap-2 px-5 py-3 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset">
            <span aria-hidden="true" className="absolute inset-0 -z-10 group-hover:bg-muted/40" />
            <span className="flex items-center gap-3">
              <ChevronRightIcon
                aria-hidden="true"
                className={cn("size-4 shrink-0 text-muted-foreground motion-safe:transition-transform", open && "rotate-90")}
              />
              <span className="min-w-0 flex-1 text-sm font-medium">{objective.title}</span>
              <PersonAvatar person={owner} />
              <ConfidencePill state={confidence} className="hidden @sm:inline-flex" />
            </span>
            <span className="flex items-center gap-3 pl-7">
              <ProgressBar value={shown ? percent : 0} label={`${objective.title} progress`} fill={BAR_FILL[confidence]} delay={0.35} />
              <RollingText text={`${Math.round(percent)}%`} className="w-10 justify-end text-sm font-medium" />
            </span>
          </DisclosureTrigger>
        </h3>
        <Disclosed>
          <ul aria-label={`Key results for ${objective.title}`} className="flex flex-col gap-3 pr-5 pb-4 pl-12">
            {objective.results.map((result) => (
              <li key={result.id} className="flex flex-col gap-2">
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
                  <span className="min-w-0 flex-1 text-sm">{result.title}</span>
                  <span className="text-xs tabular-nums text-muted-foreground">
                    {formatValue.format(result.current)}
                    {result.unit} of {formatValue.format(result.target)}
                    {result.unit}
                  </span>
                  {editable && checkingIn !== result.id ? (
                    <Button variant="outline" size="sm" onClick={() => onCheckIn(result.id)}>
                      Check in<span className="sr-only"> on {result.title}</span>
                    </Button>
                  ) : null}
                </div>
                <ProgressBar value={shown ? resultPercent(result) : 0} label={`${result.title} progress`} fill={BAR_FILL[result.confidence]} />
                {checkingIn === result.id ? (
                  <CheckInForm result={result} onCancel={() => onCheckIn(null)} onSave={(next) => onSave(result.id, next)} />
                ) : null}
              </li>
            ))}
          </ul>
        </Disclosed>
      </li>
    </Disclosure>
  );
}

import { cn } from "@/lib/utils";

import { HUE_BORDER, HUE_FILL, type Person } from "./people";

/** Props for one person's initials badge. */
export interface PersonAvatarProps {
  person: Person;
  /** `sm` is 1.5rem, `md` is 2rem. */
  size?: "sm" | "md";
  /** Shows the name to screen readers. Leave it off when the name is already written beside the badge. */
  labelled?: boolean;
  className?: string;
}

/**
 * A round badge with a person's initials, ringed and tinted in their hue. The
 * tint is a faded layer behind the letters, so the letters keep full contrast.
 */
export function PersonAvatar({ person, size = "sm", labelled = false, className }: PersonAvatarProps) {
  return (
    <span
      role={labelled ? "img" : undefined}
      aria-label={labelled ? person.name : undefined}
      aria-hidden={labelled ? undefined : true}
      title={person.name}
      className={cn(
        "relative isolate inline-grid shrink-0 place-items-center overflow-hidden rounded-full border-2 bg-card font-semibold text-foreground",
        HUE_BORDER[person.hue],
        size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
        className,
      )}
    >
      <span aria-hidden="true" className={cn("absolute inset-0 -z-10 opacity-25", HUE_FILL[person.hue])} />
      {person.initials}
    </span>
  );
}

/** Props for a row of overlapping initials badges. */
export interface AvatarStackProps {
  people: Person[];
  /** Badges past this count fold into a "+N" badge. */
  max?: number;
  size?: "sm" | "md";
  className?: string;
}

/** A row of overlapping initials badges, named as one group, such as the people on a project. */
export function AvatarStack({ people, max = 4, size = "sm", className }: AvatarStackProps) {
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <span
      role="img"
      aria-label={people.map((member) => member.name).join(", ")}
      className={cn("flex items-center -space-x-1.5", className)}
    >
      {shown.map((member) => (
        <PersonAvatar key={member.id} person={member} size={size} className="ring-2 ring-card" />
      ))}
      {rest > 0 ? (
        <span
          aria-hidden="true"
          className={cn(
            "inline-grid shrink-0 place-items-center rounded-full border-2 border-border bg-card font-medium text-muted-foreground ring-2 ring-card",
            size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
          )}
        >
          +{rest}
        </span>
      ) : null}
    </span>
  );
}

