"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

/** Props for a thin bar that shows how much of something is done. */
export interface ProgressBarProps {
  /** From 0 to 100. */
  value: number;
  /** Names the bar for screen readers, such as "Sprint progress". */
  label: string;
  /** The fill class, such as `bg-chart-2`. */
  fill?: string;
  /** Delay before the fill moves, in seconds, so a parent bar can follow its child. */
  delay?: number;
  className?: string;
}

/**
 * A rounded progress bar that grows from the left on first show and glides to
 * each new value. It grows with a scale transform only, and it is instant under
 * reduced motion.
 */
export function ProgressBar({ value, label, fill = "bg-chart-2", delay = 0, className }: ProgressBarProps) {
  const reduceMotion = useReducedMotion();
  const clamped = Math.max(0, Math.min(100, value));
  return (
    <span
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(clamped)}
      className={cn("relative block h-1.5 w-full overflow-hidden rounded-full", className)}
    >
      {/* The track is its own faded layer, so a see-through card does not stack two tints. */}
      <span aria-hidden="true" className="absolute inset-0 bg-muted-foreground/20" />
      <motion.span
        aria-hidden="true"
        className={cn("absolute inset-0 origin-left rounded-full", fill)}
        initial={reduceMotion ? false : { scaleX: 0 }}
        animate={{ scaleX: clamped / 100 }}
        transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 160, damping: 26, delay }}
      />
    </span>
  );
}

"use client";

import { type FormEvent, type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

import type { Status } from "../../lib/status";
import { CONFIDENCE_WORD } from "./confidence-pill";
import { type KeyResult, resultPercent } from "./data";

/** Props for the check-in form under one key result. */
export interface CheckInFormProps {
  result: KeyResult;
  onSave: (next: { current: number; confidence: Status; note: string }) => void;
  onCancel: () => void;
}

const OPTIONS = (["good", "watch", "bad"] as const).map((value) => ({ value, label: CONFIDENCE_WORD[value] }));

/**
 * Records a new value for one key result. The value field opens selected, so
 * a person can type over it at once. The form shows the old and new percent
 * before saving. Escape cancels.
 */
export function CheckInForm({ result, onSave, onCancel }: CheckInFormProps) {
  const [value, setValue] = useState(String(result.current));
  const [confidence, setConfidence] = useState<Status>(result.confidence);
  const [note, setNote] = useState("");
  const valueRef = useRef<HTMLInputElement>(null);
  const valueId = useId();
  const noteId = useId();

  useEffect(() => {
    valueRef.current?.select();
  }, []);

  const parsed = Number(value);
  const valid = value.trim() !== "" && Number.isFinite(parsed);
  const before = Math.round(resultPercent(result));
  const after = valid ? Math.round(resultPercent({ ...result, current: parsed })) : before;

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (valid) onSave({ current: parsed, confidence, note });
  };

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key === "Escape") {
      event.stopPropagation();
      onCancel();
    }
  };

  return (
    <form
      onSubmit={submit}
      onKeyDown={onKeyDown}
      aria-label={`Check in on ${result.title}`}
      className="flex flex-col gap-3 rounded-xl border border-border p-3"
    >
      <div className="flex flex-wrap items-end gap-3">
        <label htmlFor={valueId} className="flex flex-col gap-1 text-xs text-muted-foreground">
          New value, target {result.target}
          {result.unit}
          <Input
            ref={valueRef}
            id={valueId}
            inputMode="decimal"
            value={value}
            onChange={(event) => setValue(event.target.value)}
            aria-invalid={!valid}
            className="w-28"
          />
        </label>
        <SegmentedControl aria-label="Confidence" options={OPTIONS} value={confidence} onValueChange={setConfidence} />
      </div>
      <label htmlFor={noteId} className="flex flex-col gap-1 text-xs text-muted-foreground">
        Note for the team
        <Textarea
          id={noteId}
          value={note}
          onChange={(event) => setNote(event.target.value)}
          placeholder="What moved this week, and what is in the way"
          rows={2}
        />
      </label>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm tabular-nums text-muted-foreground" aria-live="polite">
          {before}% to <span className="font-medium text-foreground">{after}%</span>
        </p>
        <div className="flex gap-2">
          <Button type="button" variant="ghost" size="sm" onClick={onCancel}>
            Cancel
          </Button>
          <Button type="submit" size="sm" disabled={!valid}>
            Save check-in
          </Button>
        </div>
      </div>
    </form>
  );
}

